export interface CirclebackConfig {
  /** Stable pipeline/stream namespace. Change when switching accounts or filters. */
  sourceId: string
  sourceIdentity: string
  database: string
  ownership: string
  /** Bounds acknowledged parents and transcript availability diagnostics. */
  maxRetainedMeetings: number
}

export type CirclebackReaderConfig = Omit<CirclebackConfig, 'database'>

// Storage is configured before schema discovery; credentials are read at request time.
export const circlebackConfig: CirclebackConfig = {
  sourceId: 'circleback',
  sourceIdentity: 'circleback.primary',
  database: 'default',
  ownership: 'All',
  maxRetainedMeetings: 10_000,
}

import { HttpError, IngestConfigError, paginate, type FetchContext } from '@chkit/plugin-ingest'

import { circlebackConfig, type CirclebackReaderConfig } from './config.js'

const baseUrl = 'https://circleback.ai/api'

interface Meeting { id: string; [key: string]: unknown }

export interface CirclebackClientDeps {
  config: CirclebackReaderConfig
  fetch: (url: string, init: RequestInit) => Promise<Response>
  token: () => string | undefined
}

export const defaultCirclebackClientDeps: CirclebackClientDeps = {
  config: circlebackConfig,
  fetch: (url, init) => fetch(url, init),
  token: () => process.env.CIRCLEBACK_API_KEY,
}

export function readMeetingPages(context: FetchContext, deps: CirclebackClientDeps) {
  return paginate({
    context, initial: `${baseUrl}/meetings?ownership=${encodeURIComponent(deps.config.ownership)}`, label: 'GET /meetings',
    fetchPage: async (cursor, signal) => {
      if (!cursor) throw new IngestConfigError('Circleback meeting page URL is missing.')
      const response = await request(cursor, signal, deps)
      const items: unknown = await response.json()
      if (!Array.isArray(items) || !items.every(isMeeting)) throw new IngestConfigError('Circleback returned invalid meetings.')
      return { items, next: nextLink(response.headers.get('link'), cursor) }
    },
  })
}

export async function readTranscript(id: string, signal: AbortSignal, deps: CirclebackClientDeps) {
  const response = await request(`${baseUrl}/meeting/${encodeURIComponent(id)}/transcript`, signal, deps, true)
  if (response.status === 403) return { transcript: null, status: 'forbidden' as const }
  if (response.status === 404) return { transcript: null, status: 'not_found' as const }
  return { transcript: await response.json(), status: 'available' as const }
}

async function request(url: string, signal: AbortSignal, deps: CirclebackClientDeps, allowUnavailable = false): Promise<Response> {
  const token = deps.token()?.trim()
  if (!token) throw new IngestConfigError('Set CIRCLEBACK_API_KEY.')
  const response = await deps.fetch(url, {
    signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), redirect: 'error',
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
  })
  if (allowUnavailable && (response.status === 403 || response.status === 404)) return response
  if (!response.ok) throw await HttpError.fromResponse(response)
  return response
}

function nextLink(header: string | null, current: string): string | undefined {
  const value = header?.split(',').map((part) => /<([^>]+)>\s*;.*rel="?next"?/.exec(part)?.[1]).find(Boolean)
  if (!value) return undefined
  const next = new URL(value, current)
  if (next.origin !== 'https://circleback.ai') throw new IngestConfigError('Circleback next page has an unexpected origin.')
  return next.toString()
}

function isMeeting(value: unknown): value is Meeting {
  return typeof value === 'object' && value !== null && 'id' in value && typeof value.id === 'string' && value.id.length > 0
}

import { definePipeline, defineStream, IngestConfigError } from '@chkit/plugin-ingest'

import { defaultCirclebackClientDeps, type CirclebackClientDeps } from './client.js'
import { circlebackConfig, type CirclebackReaderConfig } from './config.js'
import { circleback_meetingsRaw, createMeetingStrategy, readMeetings } from './sources/meetings.js'

export function createCirclebackPipeline(config: CirclebackReaderConfig = circlebackConfig, deps: CirclebackClientDeps = defaultCirclebackClientDeps) {
  if (!config.sourceId.trim() || !config.sourceIdentity.trim() || !config.ownership.trim() ||
    !Number.isSafeInteger(config.maxRetainedMeetings) || config.maxRetainedMeetings <= 0) {
    throw new IngestConfigError('Circleback needs source identities, ownership, and a positive maxRetainedMeetings.')
  }
  const client = { ...deps, config: { ...config } }
  return definePipeline({
    id: config.sourceId, tags: ['provider:circleback'], maxStreams: 1, maxFetches: 1,
    streams: [defineStream({
      id: `${config.sourceId}.meetings`, tags: ['resource:meetings'], destination: circleback_meetingsRaw,
      incremental: createMeetingStrategy(client.config),
      // Each meeting's enrichment and recovery state must be acknowledged together.
      batchSize: 1,
      read: (context) => readMeetings(context, client),
    })],
  })
}

export const circlebackPipeline = createCirclebackPipeline()

import { cursorState, IngestConfigError, rawRows, rawTable, type ReadContext } from '@chkit/plugin-ingest'

import { readMeetingPages, readTranscript, type CirclebackClientDeps } from '../client.js'
import { circlebackConfig, type CirclebackReaderConfig } from '../config.js'

interface UnavailableTranscript { id: string; status: 'forbidden' | 'not_found'; checkedAt: string }
interface ScanCycle { startedAt: string; completedMeetingIds: string[] }
interface ScanState { scope: string; completedAt: string | null; scan: ScanCycle | null; unavailableTranscripts: UnavailableTranscript[] }

export const circleback_meetingsRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_meetings_raw' })

/** One resource collection; parent IDs below are recovery positions, never individual streams. */
export async function* readMeetings(context: ReadContext<ScanState | undefined, ScanState>, deps: CirclebackClientDeps) {
  const unavailable = new Map(context.state?.unavailableTranscripts.map((item) => [item.id, item]) ?? [])
  const completed = new Set(context.state?.scan?.completedMeetingIds ?? [])
  const startedAt = context.state?.scan?.startedAt ?? context.cutoff.toISOString()
  const scope = sourceScope(deps.config)
  for await (const meetings of readMeetingPages(context, deps)) {
    for (const meeting of meetings) {
      // Restart mutable listing pages; skip only sink-acknowledged enrichment in the active cycle.
      if (completed.has(meeting.id)) continue
      if (completed.size >= deps.config.maxRetainedMeetings) throw new IngestConfigError('Circleback scan exceeds maxRetainedMeetings; raise that source setting before resuming.')
      const outcome = await context.attempt((signal) => readTranscript(meeting.id, signal, deps), { label: 'GET meeting transcript' })
      if (outcome.status === 'available') unavailable.delete(meeting.id)
      else unavailable.set(meeting.id, { id: meeting.id, status: outcome.status, checkedAt: context.cutoff.toISOString() })
      if (unavailable.size > deps.config.maxRetainedMeetings) throw new IngestConfigError('Circleback unavailable diagnostics exceed maxRetainedMeetings; resolve old entries or raise that source setting.')
      completed.add(meeting.id)
      yield {
        rows: rawRows([{ ...meeting, transcript: outcome.transcript, _chkit_transcript_status: outcome.status }], (item) => item.id),
        state: { scope, completedAt: context.state?.completedAt ?? null,
          scan: { startedAt, completedMeetingIds: [...completed] }, unavailableTranscripts: [...unavailable.values()] },
      }
    }
  }
  // Next run rechecks every listed meeting; absent unavailable IDs remain diagnostics, not pending work.
  yield { rows: [], state: { scope, completedAt: context.cutoff.toISOString(), scan: null,
    unavailableTranscripts: [...unavailable.values()] }, id: `completed-scan:${startedAt}` }
}

export function createMeetingStrategy(config: CirclebackReaderConfig) {
  return cursorState<ScanState>({
    id: 'circleback.meetings.full_scan', version: 2,
    parse: (raw) => parseState(raw, config),
  })
}

function parseState(raw: unknown, config: CirclebackReaderConfig): ScanState {
  const scope = sourceScope(config)
  if (!isObject(raw) || raw.scope !== scope || (raw.completedAt !== null && !isTimestamp(raw.completedAt)) ||
    (raw.scan !== null && !isScan(raw.scan, config.maxRetainedMeetings)) || !Array.isArray(raw.unavailableTranscripts) ||
    raw.unavailableTranscripts.length > config.maxRetainedMeetings || !raw.unavailableTranscripts.every(isUnavailable) ||
    new Set(raw.unavailableTranscripts.map((item) => item.id)).size !== raw.unavailableTranscripts.length) {
    throw new IngestConfigError('Circleback checkpoint is invalid or its source/filter scope changed; use a new stream identity for a different source.')
  }
  return { scope, completedAt: raw.completedAt, scan: raw.scan, unavailableTranscripts: raw.unavailableTranscripts }
}

function sourceScope(config: CirclebackReaderConfig): string {
  return JSON.stringify({ sourceIdentity: config.sourceIdentity, ownership: config.ownership })
}

function isScan(value: unknown, max: number): value is ScanCycle {
  return isObject(value) && isTimestamp(value.startedAt) && Array.isArray(value.completedMeetingIds) &&
    value.completedMeetingIds.length <= max && value.completedMeetingIds.every((id: unknown) => typeof id === 'string' && id.length > 0) &&
    new Set(value.completedMeetingIds).size === value.completedMeetingIds.length
}

function isUnavailable(value: unknown): value is UnavailableTranscript {
  return isObject(value) && typeof value.id === 'string' && value.id.length > 0 &&
    (value.status === 'forbidden' || value.status === 'not_found') && isTimestamp(value.checkedAt)
}

function isTimestamp(value: unknown): value is string {
  return typeof value === 'string' && Number.isFinite(Date.parse(value))
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

import { afterEach, expect, test } from 'bun:test'
import { IngestConfigError, runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { circlebackPipeline, createCirclebackPipeline } from '../index.js'
import { circlebackConfig } from '../config.js'
import { defaultCirclebackClientDeps } from '../client.js'

const originalFetch = globalThis.fetch
const originalToken = process.env.CIRCLEBACK_API_KEY

function setFetch(handler: (...args: Parameters<typeof fetch>) => Promise<Response>): void {
  globalThis.fetch = Object.assign(handler, { preconnect: originalFetch.preconnect })
}

afterEach(() => {
  globalThis.fetch = originalFetch
  if (originalToken === undefined) delete process.env.CIRCLEBACK_API_KEY
  else process.env.CIRCLEBACK_API_KEY = originalToken
})

test.serial('Circleback follows the Link cursor and joins available transcripts', async () => {
  process.env.CIRCLEBACK_API_KEY = 'fixture'
  const paths: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    paths.push(url.pathname + url.search)
    if (url.pathname.endsWith('/transcript')) return url.pathname.includes('/b/') ? new Response('', { status: 404 }) : Response.json([{ text: 'Hello' }])
    if (url.searchParams.has('cursor')) return Response.json([{ id: 'b', name: 'Second' }])
    return Response.json([{ id: 'a', name: 'First' }], { headers: { Link: '</api/meetings?cursor=next>; rel="next"' } })
  })
  const destination = createMemoryDestination()
  const result = await runIngestion({ selected: selectStreams([circlebackPipeline], []), backfill: undefined }, { journal: createMemoryJournal(), destination })
  expect(result.ok).toBe(true)
  expect(paths).toEqual(['/api/meetings?ownership=All', '/api/meeting/a/transcript', '/api/meetings?cursor=next', '/api/meeting/b/transcript'])
  const rows = destination.tables.get('default.circleback_meetings_raw') ?? []
  expect(rows.map((row) => row.id)).toEqual(['a', 'b'])
  expect(rows[0]?.raw).toMatchObject({ transcript: [{ text: 'Hello' }] })
  expect(rows[1]?.raw).toMatchObject({ transcript: null })
})

test.serial('Circleback retains unavailable transcripts and retries them when metadata has not changed', async () => {
  process.env.CIRCLEBACK_API_KEY = 'fixture'
  let available = false
  const listingStarts: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    if (url.pathname.endsWith('/transcript')) {
      if (available) return Response.json([{ text: 'ready' }])
      return new Response('unavailable', { status: url.pathname.includes('/a/') ? 403 : 404 })
    }
    listingStarts.push(url.search)
    return Response.json([{ id: 'a', updatedAt: '2025-01-01' }, { id: 'b', updatedAt: '2025-01-01' }])
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selectStreams([circlebackPipeline], []), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-01') })).ok).toBe(true)
  expect((await journal.readCheckpoint('circleback.meetings')).envelope?.state).toEqual({
    scope: JSON.stringify({ sourceIdentity: 'circleback.primary', ownership: 'All' }), scan: null,
    completedAt: '2026-01-01T00:00:00.000Z', unavailableTranscripts: [
      { id: 'a', status: 'forbidden', checkedAt: '2026-01-01T00:00:00.000Z' },
      { id: 'b', status: 'not_found', checkedAt: '2026-01-01T00:00:00.000Z' },
    ],
  })
  available = true
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-02') })).ok).toBe(true)
  expect((await journal.readCheckpoint('circleback.meetings')).envelope?.state).toMatchObject({ completedAt: '2026-01-02T00:00:00.000Z', scan: null, unavailableTranscripts: [] })
  expect(listingStarts).toEqual(['?ownership=All', '?ownership=All'])
  expect(destination.tables.get('default.circleback_meetings_raw')?.at(-1)?.raw).toMatchObject({ transcript: [{ text: 'ready' }], _chkit_transcript_status: 'available' })
})

test.serial('Circleback sink failures do not commit enrichment state', async () => {
  process.env.CIRCLEBACK_API_KEY = 'fixture'
  setFetch(async (input) => String(input).endsWith('/transcript') ? new Response('unavailable', { status: 404 }) : Response.json([{ id: 'a' }]))
  const journal = createMemoryJournal()
  const selected = selectStreams([circlebackPipeline], []).map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 0 } } }))
  const result = await runIngestion({ selected, backfill: undefined }, {
    journal, destination: { insert: async () => { throw new IngestConfigError('sink rejected') } },
  })
  expect(result.ok).toBe(false)
  expect((await journal.readCheckpoint('circleback.meetings')).envelope).toBeUndefined()
})

test.serial('Circleback fails incomplete pagination without committing scan completion and restarts from the first page', async () => {
  process.env.CIRCLEBACK_API_KEY = 'fixture'
  let fail = true
  const starts: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    if (url.pathname.endsWith('/transcript')) return new Response('unavailable', { status: 404 })
    if (url.searchParams.has('cursor')) return fail ? new Response('denied', { status: 403 }) : Response.json([])
    starts.push(url.search)
    return Response.json([{ id: 'a' }], { headers: { Link: '</api/meetings?cursor=next>; rel="next"' } })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const selected = selectStreams([circlebackPipeline], []).map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 0 } } }))
  const request = { selected, backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-01') })).ok).toBe(false)
  expect((await journal.readCheckpoint('circleback.meetings')).envelope?.state).toMatchObject({ completedAt: null, unavailableTranscripts: [{ id: 'a' }] })
  fail = false
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-02') })).ok).toBe(true)
  expect(starts).toEqual(['?ownership=All', '?ownership=All'])
  expect((await journal.readCheckpoint('circleback.meetings')).envelope?.state).toMatchObject({ completedAt: '2026-01-02T00:00:00.000Z' })
})

test.serial('Circleback replays unfinished enrichment while skipping acknowledged parents until the next full cycle', async () => {
  process.env.CIRCLEBACK_API_KEY = 'fixture'
  let failSecond = true
  const transcripts: string[] = []
  const journal = createMemoryJournal()
  let acknowledgeFirst = () => {}
  const firstCommitted = new Promise<void>((resolve) => { acknowledgeFirst = resolve })
  const append = journal.append
  journal.append = async (events) => {
    await append(events)
    if (events.some((event) => JSON.stringify(event.checkpoint?.state)?.includes('"completedMeetingIds":["a"]'))) acknowledgeFirst()
  }
  setFetch(async (input) => {
    const url = new URL(String(input))
    if (!url.pathname.endsWith('/transcript')) return Response.json([{ id: 'a', custom: 'first' }, { id: 'b', custom: 'second' }])
    const id = url.pathname.includes('/a/') ? 'a' : 'b'
    transcripts.push(id)
    if (id === 'b' && failSecond) {
      await firstCommitted
      return new Response('temporarily unavailable', { status: 500 })
    }
    return Response.json([{ text: id }])
  })
  const destination = createMemoryDestination()
  const selected = selectStreams([circlebackPipeline], []).map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 0 } } }))
  const request = { selected, backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-01') })).ok).toBe(false)
  expect((await journal.readCheckpoint('circleback.meetings')).envelope?.state).toMatchObject({
    completedAt: null, scan: { startedAt: '2026-01-01T00:00:00.000Z', completedMeetingIds: ['a'] },
  })
  failSecond = false
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-02') })).ok).toBe(true)
  expect(transcripts).toEqual(['a', 'b', 'b'])
  expect((await journal.readCheckpoint('circleback.meetings')).envelope?.state).toMatchObject({ completedAt: '2026-01-02T00:00:00.000Z', scan: null })
  expect(destination.tables.get('default.circleback_meetings_raw')?.map((row) => row.id)).toEqual(['a', 'b'])
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-03') })).ok).toBe(true)
  expect(transcripts).toEqual(['a', 'b', 'b', 'a', 'b'])
})

test.serial('Circleback empty scans complete and retain absent unavailable IDs as diagnostics', async () => {
  process.env.CIRCLEBACK_API_KEY = 'fixture'
  let listed = true
  const transcripts: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    if (url.pathname.endsWith('/transcript')) {
      transcripts.push(url.pathname)
      return new Response('not found', { status: 404 })
    }
    return Response.json(listed ? [{ id: 'a' }] : [])
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selectStreams([circlebackPipeline], []), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-01') })).ok).toBe(true)
  listed = false
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-02') })).ok).toBe(true)
  expect(transcripts).toHaveLength(1)
  expect((await journal.readCheckpoint('circleback.meetings')).envelope?.state).toMatchObject({
    completedAt: '2026-01-02T00:00:00.000Z', scan: null,
    unavailableTranscripts: [{ id: 'a', status: 'not_found', checkedAt: '2026-01-01T00:00:00.000Z' }],
  })
})

test('Circleback rejects changed source scopes and unbounded or duplicated recovery IDs', () => {
  const parse = circlebackPipeline.streams[0]?.incremental.parseState
  expect(parse).toBeDefined()
  const state = { scope: JSON.stringify({ sourceIdentity: 'circleback.primary', ownership: 'All' }), completedAt: null, scan: null, unavailableTranscripts: [] }
  expect(() => parse?.({ ...state, scope: 'different-source' })).toThrow('scope changed')
  expect(() => parse?.({ ...state, scan: { startedAt: '2026-01-01T00:00:00Z', completedMeetingIds: ['a', 'a'] } })).toThrow('checkpoint is invalid')
  expect(() => parse?.({ ...state, scan: { startedAt: '2026-01-01T00:00:00Z', completedMeetingIds: Array.from({ length: 10_001 }, (_, index) => String(index)) } })).toThrow('checkpoint is invalid')
})

test('Circleback binds source scope and bounds to its meeting collection without creating streams per meeting', async () => {
  const config = { ...circlebackConfig, sourceId: 'circleback.team', sourceIdentity: 'team', maxRetainedMeetings: 2 }
  const calls: string[] = []
  const pipeline = createCirclebackPipeline(config, {
    ...defaultCirclebackClientDeps, token: () => 'team-key',
    fetch: async (url, init) => {
      calls.push(url)
      expect(init.headers).toEqual({ Authorization: 'Bearer team-key', Accept: 'application/json' })
      return url.endsWith('/transcript') ? new Response('unavailable', { status: 404 }) : Response.json([{ id: 'a' }, { id: 'b' }])
    },
  })
  config.sourceIdentity = 'changed-after-construction'
  config.maxRetainedMeetings = 1
  expect(selectStreams([pipeline], ['resource:meetings']).map((item) => item.stream.id)).toEqual(['circleback.team.meetings'])
  const journal = createMemoryJournal()
  const result = await runIngestion({ selected: selectStreams([pipeline], ['resource:meetings']), backfill: undefined }, { journal, destination: createMemoryDestination() })
  expect(result.ok).toBe(true)
  expect(calls).toEqual(['https://circleback.ai/api/meetings?ownership=All', 'https://circleback.ai/api/meeting/a/transcript', 'https://circleback.ai/api/meeting/b/transcript'])
  const state = (await journal.readCheckpoint('circleback.team.meetings')).envelope?.state
  expect(state).toMatchObject({ scope: JSON.stringify({ sourceIdentity: 'team', ownership: 'All' }), scan: null })
  expect((await journal.readCheckpoint('circleback.meetings')).envelope).toBeUndefined()
  const changedScope = createCirclebackPipeline({ ...circlebackConfig, sourceIdentity: 'another-account' })
  expect(() => changedScope.streams[0]?.incremental.parseState(state)).toThrow('scope changed')
})

test('Circleback rejects cyclic Link pagination and unexpected origins without completing the cycle', async () => {
  for (const next of ['/api/meetings?cursor=repeat', 'https://untrusted.example/meetings']) {
    const calls: string[] = []
    const pipeline = createCirclebackPipeline(circlebackConfig, {
      ...defaultCirclebackClientDeps, token: () => 'fixture', fetch: async (url) => {
        calls.push(url)
        return Response.json([], { headers: { Link: `<${next}>; rel="next"` } })
      },
    })
    const journal = createMemoryJournal()
    const result = await runIngestion({ selected: selectStreams([pipeline], []), backfill: undefined }, { journal, destination: createMemoryDestination() })
    expect(result.ok).toBe(false)
    expect(calls).toHaveLength(next.startsWith('/') ? 2 : 1)
    expect((await journal.readCheckpoint('circleback.meetings')).lastSuccessSeq).toBe(0)
    expect((await journal.readCheckpoint('circleback.meetings')).envelope).toBeUndefined()
  }
})
